import sys

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Group indices by value
    value_to_indices = {}
    for i in range(n):
        if a[i] not in value_to_indices:
            value_to_indices[a[i]] = []
        value_to_indices[a[i]].append(i)

    total = 0

    # For each value that appears
    for value, indices in value_to_indices.items():
        m = len(indices)
        if m < 2:
            continue

        # Calculate sum of (p_j - p_i) for all i < j
        sum_diff = 0
        for j in range(m):
            sum_diff += indices[j] * j
        for i in range(m):
            sum_diff -= indices[i] * (m - 1 - i)

        # Calculate sum of count_between for all pairs (i,j) where i < j
        sum_between = 0
        for k in range(1, m - 1):
            sum_between += k * (m - 1 - k)

        # Total contribution for this value
        # Σ(i<j) (p_j - p_i - 1 - count_between) = (sum_diff - C(m,2)) - sum_between
        total_pairs = m * (m - 1) // 2
        total += (sum_diff - total_pairs - sum_between)

    print(total)

