def solve():
    T = input().strip()
    N = int(input().strip())

    bags = []
    for _ in range(N):
        line = input().split()
        A_i = int(line[0])
        strings = line[1:A_i + 1]
        bags.append(strings)

    # dp[position] = minimum cost to reach this position in T
    dp = {0: 0}

    for bag_idx in range(N):
        new_dp = dp.copy()

        for current_pos, cost in dp.items():
            for string in bags[bag_idx]:
                new_pos = current_pos + len(string)
                if new_pos <= len(T):
                    # Check if the string matches the required substring
                    if T[current_pos:new_pos] == string:
                        new_cost = cost + 1
                        if new_pos not in new_dp or new_dp[new_pos] > new_cost:
                            new_dp[new_pos] = new_cost

        dp = new_dp

    return dp.get(len(T), -1)

